namespace PythonManager {
static class Program {
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{
  if(args.Length==3&&args[0]=="--set-default"){Core.SetDefault(Core.Inspect(args[1]));Core.Save(args[2],new{Default=Core.DefaultExecutable()});return 0;}
  Application.Run(new ManagerForm());return 0;
 }catch(Exception e){MessageBox.Show(e.Message,"Python 环境管家",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
}
