 async Task Work(Func<Task> work){if(busy)return;busy=true;UseWaitCursor=true;tabs.Enabled=false;try{await work();}catch(Exception e){Error(e);}finally{busy=false;UseWaitCursor=false;tabs.Enabled=true;}}
