  var optionsGroup=new GroupBox{Text="本题解释器参数（可留空，每行一个；仅用于脚本运行页）",Dock=DockStyle.Fill,Padding=new Padding(10,22,10,7)};projectOptions=Box(true);projectOptions.AccessibleName="题目解释器参数";optionsGroup.Controls.Add(projectOptions);grid.Controls.Add(optionsGroup);
 }
 void BuildRunner(){var grid=Page("运行脚本与日志",new float[]{38,42,30,46,30,115,48,-1,36});useProject=new CheckBox{Text="使用 CTF 题目页已保存的环境（版本、依赖和工作目录固定）",Dock=DockStyle.Fill};useProject.CheckedChanged+=delegate{runPython.Enabled=!useProject.Checked;scriptOptions.Enabled=!useProject.Checked;};grid.Controls.Add(useProject);
