 void Append(string line){if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new Action<string>(Append),line);return;}if(output.TextLength>200000)output.Text=output.Text.Substring(output.TextLength-120000);output.AppendText(line+Environment.NewLine);}
 void UpdateDefault(){string exe=Core.DefaultExecutable();PythonRuntime runtime=runtimes.FirstOrDefault(x=>Core.Same(x.Executable,exe));defaultLabel.Text="日常默认："+(runtime!=null?"Python "+runtime.Version+"  /  "+runtime.Architecture:"由现有入口决定（可点击设置默认）")+"    · 题目虚拟环境独立保存";}
 async Task RefreshVersions(){await Work(async delegate{List<string> errors=null;runtimes=await Task.Run(()=>Core.Scan(out errors));list.Items.Clear();projectPython.Items.Clear();runPython.Items.Clear();foreach(PythonRuntime p in runtimes){list.Items.Add(new ListViewItem(new[]{p.Name,p.Version,p.Architecture,p.Executable}){Tag=p});projectPython.Items.Add(p);runPython.Items.Add(p);}string actual=Core.DefaultExecutable();PythonRuntime current=runtimes.FirstOrDefault(p=>Core.Same(p.Executable,actual))??runtimes.LastOrDefault();if(current!=null){list.Items[runtimes.IndexOf(current)].Selected=true;projectPython.SelectedItem=current;runPython.SelectedItem=current;}RefreshRecent();UpdateDefault();status.Text="已识别 "+runtimes.Count+" 套 Python。"+(errors.Count>0?String.Join("；",errors):"每道题目创建独立虚拟环境，互不干扰。");});}
 void RefreshRecent(string keep=null){recent.Items.Clear();foreach(string path in Core.Config().RecentProjects)recent.Items.Add(path);if(keep!=null)recent.SelectedItem=keep;}
 void LoadView(){string folder=Folder();string file=Path.Combine(folder,Core.PinName);if(!File.Exists(file)){pinStatus.Text="此题目尚未绑定；选择 Python 后点击“创建题目环境”。";projectOptions.Clear();return;}ProjectPin pin=Core.Read<ProjectPin>(file);if(pin==null)throw new InvalidDataException("题目绑定文件无效。");projectOptions.Lines=pin.Options??new string[0];projectPython.SelectedItem=runtimes.FirstOrDefault(x=>Core.Same(x.Executable,pin.BaseExecutable));pinStatus.Text="已记录：Python "+pin.Version+" / "+pin.Architecture+"\n环境："+pin.Executable+"\n启动时验证解释器指纹和依赖清单；不会自动回退版本。";}
 async Task OpenProject(bool ps){string folder=Folder();await Work(async delegate{ProjectPin pin=await Task.Run(()=>Core.LoadPin(folder,true));Core.OpenTerminal(pin.Executable,folder,ps);Core.Remember(folder);status.Text="已打开题目独立终端：Python "+pin.Version+"。python / pip 指向该题环境。";});}
 async Task Logged(string label,Func<Action<string>,Action<Process>,CommandResult> execute){
  if(busy)return;busy=true;UseWaitCursor=true;tabs.Enabled=true;active=null;tabs.SelectedIndex=2;output.Clear();Append(label);string directory=Path.Combine(Core.DataRoot,"logs");Directory.CreateDirectory(directory);string log=Path.Combine(directory,DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")+".log");Append("日志："+log);try{
   using(StreamWriter writer=new StreamWriter(log,false,new UTF8Encoding(false))){writer.AutoFlush=true;writer.WriteLine(label);object gate=new object();Action<string> emit=delegate(string text){lock(gate)writer.WriteLine(text);Append(text);};CommandResult result=await Task.Run(()=>execute(emit,p=>active=p));emit("任务结束，退出代码："+result.ExitCode);status.Text=result.ExitCode==0?"操作已完成；日常默认和其他题目保持不变。":"操作未成功，详细原因见日志。安装失败后请检查依赖再更新记录。";}
  }catch(Exception e){Append(e.Message);Error(e);}finally{active=null;busy=false;UseWaitCursor=false;}}
 async Task PipAction(string[] args){string folder=Folder();await Logged("题目依赖操作："+Core.Args(args),delegate(Action<string> emit,Action<Process> started){return Core.Pip(folder,args,emit,started);});}
 async Task RunScript(){string script=scriptFile.Text.Trim();string folder;string exe;string[] options;
  try{if(useProject.Checked){folder=Folder();ProjectPin pin=Core.LoadPin(folder,true);exe=pin.Executable;options=pin.Options;}else{PythonRuntime selected=(PythonRuntime)runPython.SelectedItem;if(selected==null)throw new InvalidOperationException("请选择 Python 版本。");exe=selected.Executable;folder=Path.GetDirectoryName(Path.GetFullPath(script));options=Lines(scriptOptions);}string[] args=Lines(scriptArgs);ProcessStartInfo info=Core.Script(exe,script,folder,options,args);await Logged("解释器："+exe+Environment.NewLine+"工作目录："+folder+Environment.NewLine+"参数："+info.Arguments,(emit,started)=>Core.Run(info,86400000,emit,started));}catch(Exception e){Error(e);}
 }
}
